  j constant jsonb := $j$[
{"id":"896571ed-65f4-4dde-9e56-c9af01706a21","recipe_group_id":"bf8c875f-0372-4866-9be5-088c07d19cbe","language":"es","slug":"receta-de-pancakes-con-fresas-y-arandanos","public_path":"/receta-de-pancakes-con-fresas-y-arandanos","source_url":"https://manualdecocina.com/receta-de-pancakes-con-fresas-y-arandanos/","title":"Pancakes con fresas y arándanos","excerpt":"Pancakes esponjosos con fresas y arándanos frescos, listos en 30 minutos: masa de harina, huevo y leche con las frutas cocidas dentro y más fruta fresca por encima. Rinde 8 pancakes.","summary":"Estos pancakes se preparan con una masa sencilla de harina, huevo, leche y mantequilla derretida, aligerada con polvo de hornear. Las fresas y los arándanos se reparten sobre la masa en la sartén, así que se cocinan dentro del pancake y sueltan su jugo y su aroma.\n\nSe cocinan a fuego medio, con porciones de 60 ml de masa, y se sirven apilados con más fruta fresca y jarabe de arce. La receta rinde 8 pancakes, 2 por persona, y está lista en unos 30 minutos.","category":"Desayunos y brunch","difficulty":"Fácil","course":"Desayuno","cuisine":"Americana","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":4,"keywords":["pancakes con fresas y arándanos","pancakes de fresa","pancakes de arándanos","cómo hacer pancakes","pancakes caseros","desayuno con frutas","receta de pancakes"],"ingredients":[{"name":"harina de trigo","amount":"125","unit":"g","group":"Ingredientes secos"},{"name":"azúcar","amount":"25","unit":"g","group":"Ingredientes secos"},{"name":"polvo de hornear","amount":"8","unit":"g","group":"Ingredientes secos"},{"name":"sal","amount":"3","unit":"g","group":"Ingredientes secos"},{"name":"huevo","amount":"1","unit":"unidad","group":"Ingredientes líquidos"},{"name":"leche","amount":"240","unit":"ml","group":"Ingredientes líquidos"},{"name":"mantequilla sin sal, derretida","amount":"33","unit":"g","group":"Ingredientes líquidos"},{"name":"extracto de vainilla","amount":"5","unit":"ml","group":"Ingredientes líquidos"},{"name":"fresas en rodajas","amount":"150","unit":"g","group":"Fruta y para servir"},{"name":"arándanos frescos","amount":"100","unit":"g","group":"Fruta y para servir"},{"name":"jarabe de arce","amount":"80","unit":"ml","group":"Fruta y para servir"}],"steps":[{"title":"Mezcla los ingredientes secos","content":"En un bol grande, mezcla con unas varillas 125 g de harina (1 taza), 25 g de azúcar, 8 g de polvo de hornear (2 cucharaditas) y 3 g de sal (½ cucharadita).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-01.webp","image_alt":"Pancakes con fresas y arándanos: Mezcla los ingredientes secos"},{"title":"Bate los ingredientes líquidos","content":"En otro bol, bate 1 huevo con 240 ml de leche (1 taza), 28 g de mantequilla derretida (2 cucharadas) y 5 ml de extracto de vainilla.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-02.webp","image_alt":"Pancakes con fresas y arándanos: Bate los ingredientes líquidos"},{"title":"Une las dos mezclas","content":"Vierte los líquidos sobre los secos y mezcla con una espátula solo hasta integrar; deben quedar algunos grumos pequeños. Deja reposar la masa 5 minutos.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-03.webp","image_alt":"Pancakes con fresas y arándanos: Une las dos mezclas"},{"title":"Calienta la sartén","content":"Calienta una sartén antiadherente a fuego medio y úntala con una película fina de mantequilla (unos 5 g).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-04.webp","image_alt":"Pancakes con fresas y arándanos: Calienta la sartén"},{"title":"Vierte la masa y añade la fruta","content":"Vierte 60 ml de masa (un cucharón pequeño) por pancake. Reparte sobre cada uno un poco de fruta, en total 100 g de fresas en rodajas y 60 g de arándanos para los 8 pancakes.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-05.webp","image_alt":"Pancakes con fresas y arándanos: Vierte la masa y añade la fruta"},{"title":"Cocina y voltea","content":"Cocina 2–3 minutos, hasta que aparezcan burbujas en la superficie y los bordes se vean firmes. Voltea y cocina 1–2 minutos más, hasta que estén dorados.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-06.webp","image_alt":"Pancakes con fresas y arándanos: Cocina y voltea"},{"title":"Repite y mantén calientes","content":"Repite con el resto de la masa hasta tener 8 pancakes, untando la sartén con mantequilla si hace falta. Mantén los ya cocinados tapados con un paño limpio.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-07.webp","image_alt":"Pancakes con fresas y arándanos: Repite y mantén calientes"},{"title":"Sirve","content":"Sirve los pancakes apilados, 2 por persona, con los 50 g de fresas y 40 g de arándanos restantes por encima y jarabe de arce (unos 80 ml en total).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-08.webp","image_alt":"Pancakes con fresas y arándanos: Sirve"}],"image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","gallery":[{"url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","alt":"Pancakes con fresas y arándanos"}],"notes":"No mezcles la masa de más: unos pocos grumos son normales y hacen los pancakes más esponjosos. Si la sartén está demasiado caliente, se doran por fuera y quedan crudos por dentro; baja el fuego. Contienen gluten, huevo y lácteos. Se conservan 2 días en la nevera en un recipiente hermético y se recalientan en tostadora o sartén. También se pueden congelar separados con papel de horno hasta 1 mes.","nutrition":{"calories":352,"protein_g":7.3,"carbs_g":58,"fat_g":10.4,"sodium_mg":552,"serving_size":"2 pancakes con fruta y jarabe (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes crudos y divididos entre 4. La leche se calcula a 247 g, el huevo a 50 g, la vainilla (5 ml) a 4 g, el jarabe de arce (80 ml) a 106 g y la mantequilla a 33 g (28 g en la masa y unos 5 g para la sartén).","note":"Estimación por ración; varía con las marcas y la cantidad de jarabe que se añada. El polvo de hornear aporta la mayor parte del sodio.","inputs":[{"fdc_id":"169761","description":"Wheat flour, white, all-purpose, enriched, bleached","grams":125,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.152,"fiber_g":2.7,"sodium_mg":2}},{"fdc_id":"169655","description":"Sugars, granulated","grams":25,"per100":{"calories":387,"protein_g":0,"carbs_g":99.98,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":1}},{"fdc_id":"18369","description":"Leavening agents, baking powder, double-acting, sodium aluminum sulfate","grams":8,"per100":{"calories":53,"protein_g":0,"carbs_g":27.7,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sodium_mg":10600}},{"fdc_id":"173468","description":"Salt, table","grams":3,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}},{"fdc_id":"171287","description":"Egg, whole, raw, fresh","grams":50,"per100":{"calories":143,"protein_g":12.56,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.126,"fiber_g":0,"sodium_mg":142}},{"fdc_id":"172217","description":"Milk, whole, 3.25% milkfat, without added vitamin A and vitamin D","grams":247,"per100":{"calories":61,"protein_g":3.15,"carbs_g":4.78,"fat_g":3.27,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43}},{"fdc_id":"173430","description":"Butter, without salt","grams":33,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":51.368,"fiber_g":0,"sodium_mg":11}},{"fdc_id":"173471","description":"Vanilla extract","grams":4,"per100":{"calories":288,"protein_g":0.06,"carbs_g":12.65,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sodium_mg":9}},{"fdc_id":"167762","description":"Strawberries, raw","grams":150,"per100":{"calories":32,"protein_g":0.67,"carbs_g":7.68,"fat_g":0.3,"saturated_fat_g":0.015,"fiber_g":2,"sodium_mg":1}},{"fdc_id":"171711","description":"Blueberries, raw","grams":100,"per100":{"calories":57,"protein_g":0.74,"carbs_g":14.49,"fat_g":0.33,"saturated_fat_g":0.028,"fiber_g":2.4,"sodium_mg":1}},{"fdc_id":"169661","description":"Syrups, maple","grams":106,"per100":{"calories":260,"protein_g":0.04,"carbs_g":67.04,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sodium_mg":12}}]},"seo":{"title":"Pancakes con fresas y arándanos | Manual de Cocina","description":"Pancakes con fresas y arándanos: masa esponjosa de harina, huevo y leche, cocidos con fruta fresca y servidos con jarabe de arce. Rinde 8 pancakes.","image_variants":["/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-1x1.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-4x3.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-16x9.webp"],"faq":[{"q":"¿Puedo usar fresas o arándanos congelados?","a":"Sí, sin descongelar para que no suelten tanto jugo ni tiñan la masa. Añádelos directamente sobre la masa en la sartén y cocina 1 minuto más por cada lado."},{"q":"¿Por qué me quedan gomosos o planos?","a":"Casi siempre se debe a mezclar de más la masa o a un polvo de hornear viejo. Mezcla solo hasta integrar, deja reposar 5 minutos y comprueba que el polvo de hornear esté en fecha."},{"q":"¿Se pueden preparar con antelación?","a":"Sí. Se conservan 2 días en la nevera y hasta 1 mes en el congelador, separados con papel de horno. Recaliéntalos en tostadora o sartén hasta que estén calientes y ligeramente crujientes."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"94bf3c8e-e56a-52ad-8319-26c81ae37472","recipe_group_id":"bf8c875f-0372-4866-9be5-088c07d19cbe","language":"de","slug":"pancakes-mit-erdbeeren-und-heidelbeeren","public_path":"/de/pancakes-mit-erdbeeren-und-heidelbeeren","source_url":null,"title":"Pancakes mit Erdbeeren und Heidelbeeren","excerpt":"Fluffige Pancakes mit frischen Erdbeeren und Heidelbeeren, in 30 Minuten fertig: Teig aus Mehl, Ei und Milch mit Früchten in der Pfanne ausgebacken und frischen Früchten obendrauf. Ergibt 8 Pancakes.","summary":"Diese Pancakes entstehen aus einem einfachen Teig aus Mehl, Ei, Milch und geschmolzener Butter, der mit Backpulver locker wird. Erdbeeren und Heidelbeeren werden in der Pfanne auf den Teig gegeben und garen so im Pancake mit, wobei sie Saft und Aroma abgeben.\n\nSie werden bei mittlerer Hitze mit je 60 ml Teig gebacken und gestapelt mit weiteren frischen Früchten und Ahornsirup serviert. Das Rezept ergibt 8 Pancakes, 2 pro Person, und ist in etwa 30 Minuten fertig.","category":"Frühstück und Brunch","difficulty":"Einfach","course":"Frühstück","cuisine":"Amerikanisch","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":4,"keywords":["Pancakes mit Erdbeeren und Heidelbeeren","Erdbeerpancakes","Heidelbeerpancakes","Pancakes Rezept","Pancakes selber machen","Frühstück mit Früchten"],"ingredients":[{"name":"Weizenmehl","amount":"125","unit":"g","group":"Trockene Zutaten"},{"name":"Zucker","amount":"25","unit":"g","group":"Trockene Zutaten"},{"name":"Backpulver","amount":"8","unit":"g","group":"Trockene Zutaten"},{"name":"Salz","amount":"3","unit":"g","group":"Trockene Zutaten"},{"name":"Ei","amount":"1","unit":"Stück","group":"Flüssige Zutaten"},{"name":"Milch","amount":"240","unit":"ml","group":"Flüssige Zutaten"},{"name":"ungesalzene Butter, geschmolzen","amount":"33","unit":"g","group":"Flüssige Zutaten"},{"name":"Vanilleextrakt","amount":"5","unit":"ml","group":"Flüssige Zutaten"},{"name":"Erdbeeren, in Scheiben","amount":"150","unit":"g","group":"Früchte und zum Servieren"},{"name":"frische Heidelbeeren","amount":"100","unit":"g","group":"Früchte und zum Servieren"},{"name":"Ahornsirup","amount":"80","unit":"ml","group":"Früchte und zum Servieren"}],"steps":[{"title":"Trockene Zutaten mischen","content":"In einer großen Schüssel 125 g Mehl (1 Tasse), 25 g Zucker, 8 g Backpulver (2 Teelöffel) und 3 g Salz (½ Teelöffel) mit einem Schneebesen vermengen.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-01.webp","image_alt":"Pancakes mit Erdbeeren und Heidelbeeren: Trockene Zutaten mischen"},{"title":"Flüssige Zutaten verquirlen","content":"In einer zweiten Schüssel 1 Ei mit 240 ml Milch (1 Tasse), 28 g geschmolzener Butter (2 Esslöffel) und 5 ml Vanilleextrakt verquirlen.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-02.webp","image_alt":"Pancakes mit Erdbeeren und Heidelbeeren: Flüssige Zutaten verquirlen"},{"title":"Beide Mischungen verbinden","content":"Die flüssigen Zutaten zu den trockenen gießen und mit einem Spatel nur so lange verrühren, bis alles verbunden ist; kleine Klümpchen dürfen bleiben. Den Teig 5 Minuten ruhen lassen.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-03.webp","image_alt":"Pancakes mit Erdbeeren und Heidelbeeren: Beide Mischungen verbinden"},{"title":"Pfanne erhitzen","content":"Eine beschichtete Pfanne bei mittlerer Hitze erhitzen und mit einem dünnen Film Butter (etwa 5 g) einfetten.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-04.webp","image_alt":"Pancakes mit Erdbeeren und Heidelbeeren: Pfanne erhitzen"},{"title":"Teig eingießen und Früchte zugeben","content":"Pro Pancake 60 ml Teig (eine kleine Kelle) in die Pfanne gießen. Auf jeden etwas Obst verteilen, insgesamt 100 g Erdbeerscheiben und 60 g Heidelbeeren für alle 8 Pancakes.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-05.webp","image_alt":"Pancakes mit Erdbeeren und Heidelbeeren: Teig eingießen und Früchte zugeben"},{"title":"Backen und wenden","content":"2–3 Minuten backen, bis sich Bläschen auf der Oberfläche bilden und die Ränder fest wirken. Wenden und 1–2 Minuten weiterbacken, bis sie goldbraun sind.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-06.webp","image_alt":"Pancakes mit Erdbeeren und Heidelbeeren: Backen und wenden"},{"title":"Wiederholen und warm halten","content":"Mit dem restlichen Teig wiederholen, bis 8 Pancakes fertig sind, die Pfanne bei Bedarf mit Butter einfetten. Die fertigen Pancakes mit einem sauberen Tuch abgedeckt warm halten.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-07.webp","image_alt":"Pancakes mit Erdbeeren und Heidelbeeren: Wiederholen und warm halten"},{"title":"Servieren","content":"Die Pancakes gestapelt servieren, 2 pro Person, mit den übrigen 50 g Erdbeeren und 40 g Heidelbeeren obendrauf und Ahornsirup (insgesamt etwa 80 ml).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-08.webp","image_alt":"Pancakes mit Erdbeeren und Heidelbeeren: Servieren"}],"image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","gallery":[{"url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","alt":"Pancakes mit Erdbeeren und Heidelbeeren"}],"notes":"Den Teig nicht zu lange rühren: Ein paar Klümpchen sind normal und machen die Pancakes lockerer. Ist die Pfanne zu heiß, werden sie außen dunkel und bleiben innen roh; dann die Hitze reduzieren. Enthalten Gluten, Ei und Milch. Sie halten sich 2 Tage im Kühlschrank in einer luftdichten Dose und lassen sich im Toaster oder in der Pfanne aufwärmen. Mit Backpapier getrennt lassen sie sich bis zu 1 Monat einfrieren.","nutrition":{"calories":352,"protein_g":7.3,"carbs_g":58,"fat_g":10.4,"sodium_mg":552,"serving_size":"2 Pancakes mit Früchten und Sirup (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der rohen Zutaten und durch 4 geteilt. Die Milch wird mit 247 g gerechnet, das Ei mit 50 g, die Vanille (5 ml) mit 4 g, der Ahornsirup (80 ml) mit 106 g und die Butter mit 33 g (28 g im Teig und etwa 5 g für die Pfanne).","note":"Schätzung pro Portion; abhängig von Marken und Sirupmenge. Das Backpulver liefert den größten Teil des Natriums."},"seo":{"title":"Pancakes mit Erdbeeren und Heidelbeeren | Manual de Cocina","description":"Pancakes mit Erdbeeren und Heidelbeeren: lockerer Teig aus Mehl, Ei und Milch, mit frischen Früchten gebacken und mit Ahornsirup serviert. Ergibt 8 Pancakes.","image_variants":["/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-1x1.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-4x3.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-16x9.webp"],"faq":[{"q":"Kann ich gefrorene Erdbeeren oder Heidelbeeren verwenden?","a":"Ja, am besten ungetaut, damit sie weniger Saft abgeben und den Teig nicht färben. Direkt auf den Teig in der Pfanne geben und pro Seite 1 Minute länger backen."},{"q":"Warum werden meine Pancakes gummiartig oder flach?","a":"Meist wurde der Teig zu lange gerührt oder das Backpulver ist zu alt. Nur bis zur Verbindung rühren, 5 Minuten ruhen lassen und das Verfallsdatum des Backpulvers prüfen."},{"q":"Kann man sie vorbereiten?","a":"Ja. Sie halten sich 2 Tage im Kühlschrank und bis zu 1 Monat im Gefrierschrank, mit Backpapier getrennt. Im Toaster oder in der Pfanne aufwärmen, bis sie heiß und leicht knusprig sind."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"1bda7d47-41ec-5937-b2cc-2782b0e94926","recipe_group_id":"bf8c875f-0372-4866-9be5-088c07d19cbe","language":"en","slug":"strawberry-blueberry-pancakes","public_path":"/en/strawberry-blueberry-pancakes","source_url":null,"title":"Strawberry Blueberry Pancakes","excerpt":"Fluffy pancakes with fresh strawberries and blueberries, ready in 30 minutes: a flour, egg and milk batter cooked with fruit inside and topped with more fresh fruit. Makes 8 pancakes.","summary":"These pancakes use a simple batter of flour, egg, milk and melted butter, lightened with baking powder. The strawberries and blueberries are scattered over the batter in the pan, so they cook into the pancake and release their juice and aroma.\n\nThey are cooked over medium heat in 60 ml portions of batter and served stacked with more fresh fruit and maple syrup. The recipe makes 8 pancakes, 2 per person, in about 30 minutes.","category":"Breakfast & brunch","difficulty":"Easy","course":"Breakfast","cuisine":"American","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":4,"keywords":["strawberry blueberry pancakes","strawberry pancakes","blueberry pancakes","pancake recipe","homemade pancakes","fruit breakfast"],"ingredients":[{"name":"all-purpose flour","amount":"125","unit":"g","group":"Dry ingredients"},{"name":"sugar","amount":"25","unit":"g","group":"Dry ingredients"},{"name":"baking powder","amount":"8","unit":"g","group":"Dry ingredients"},{"name":"salt","amount":"3","unit":"g","group":"Dry ingredients"},{"name":"egg","amount":"1","unit":"piece","group":"Wet ingredients"},{"name":"milk","amount":"240","unit":"ml","group":"Wet ingredients"},{"name":"unsalted butter, melted","amount":"33","unit":"g","group":"Wet ingredients"},{"name":"vanilla extract","amount":"5","unit":"ml","group":"Wet ingredients"},{"name":"sliced strawberries","amount":"150","unit":"g","group":"Fruit and to serve"},{"name":"fresh blueberries","amount":"100","unit":"g","group":"Fruit and to serve"},{"name":"maple syrup","amount":"80","unit":"ml","group":"Fruit and to serve"}],"steps":[{"title":"Mix the dry ingredients","content":"In a large bowl, whisk together 125 g flour (1 cup), 25 g sugar, 8 g baking powder (2 teaspoons) and 3 g salt (½ teaspoon).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-01.webp","image_alt":"Strawberry Blueberry Pancakes: Mix the dry ingredients"},{"title":"Whisk the wet ingredients","content":"In another bowl, whisk 1 egg with 240 ml milk (1 cup), 28 g melted butter (2 tablespoons) and 5 ml vanilla extract.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-02.webp","image_alt":"Strawberry Blueberry Pancakes: Whisk the wet ingredients"},{"title":"Combine the two mixtures","content":"Pour the wet ingredients into the dry and stir with a spatula just until combined; a few small lumps should remain. Let the batter rest for 5 minutes.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-03.webp","image_alt":"Strawberry Blueberry Pancakes: Combine the two mixtures"},{"title":"Heat the pan","content":"Heat a nonstick skillet over medium heat and brush it with a thin film of butter (about 5 g).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-04.webp","image_alt":"Strawberry Blueberry Pancakes: Heat the pan"},{"title":"Pour the batter and add the fruit","content":"Pour 60 ml batter (a small ladle) for each pancake. Scatter a little fruit over each one, using 100 g sliced strawberries and 60 g blueberries in total for the 8 pancakes.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-05.webp","image_alt":"Strawberry Blueberry Pancakes: Pour the batter and add the fruit"},{"title":"Cook and flip","content":"Cook 2–3 minutes, until bubbles appear on the surface and the edges look set. Flip and cook 1–2 minutes more, until golden.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-06.webp","image_alt":"Strawberry Blueberry Pancakes: Cook and flip"},{"title":"Repeat and keep warm","content":"Repeat with the remaining batter until you have 8 pancakes, buttering the pan again if needed. Keep the cooked pancakes covered with a clean towel.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-07.webp","image_alt":"Strawberry Blueberry Pancakes: Repeat and keep warm"},{"title":"Serve","content":"Serve the pancakes stacked, 2 per person, topped with the remaining 50 g strawberries and 40 g blueberries and drizzled with maple syrup (about 80 ml in total).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-08.webp","image_alt":"Strawberry Blueberry Pancakes: Serve"}],"image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","gallery":[{"url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","alt":"Strawberry Blueberry Pancakes"}],"notes":"Do not overmix the batter: a few lumps are normal and keep the pancakes fluffy. If the pan is too hot they brown outside and stay raw inside; lower the heat. They contain gluten, egg and dairy. They keep 2 days in the fridge in an airtight container and reheat in a toaster or skillet. They can also be frozen, separated with parchment paper, for up to 1 month.","nutrition":{"calories":352,"protein_g":7.3,"carbs_g":58,"fat_g":10.4,"sodium_mg":552,"serving_size":"2 pancakes with fruit and syrup (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the raw ingredients and divided by 4. The milk is calculated at 247 g, the egg at 50 g, the vanilla (5 ml) at 4 g, the maple syrup (80 ml) at 106 g and the butter at 33 g (28 g in the batter and about 5 g for the pan).","note":"Estimate per serving; it varies with brands and the amount of syrup added. Baking powder provides most of the sodium."},"seo":{"title":"Strawberry Blueberry Pancakes | Manual de Cocina","description":"Strawberry blueberry pancakes: a fluffy flour, egg and milk batter cooked with fresh fruit and served with maple syrup. Makes 8 pancakes.","image_variants":["/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-1x1.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-4x3.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-16x9.webp"],"faq":[{"q":"Can I use frozen strawberries or blueberries?","a":"Yes, straight from the freezer so they release less juice and do not stain the batter. Place them on the batter in the pan and cook 1 minute longer per side."},{"q":"Why are my pancakes rubbery or flat?","a":"Usually the batter was overmixed or the baking powder is old. Mix only until combined, let the batter rest 5 minutes and check the baking powder is in date."},{"q":"Can I make them ahead?","a":"Yes. They keep 2 days in the fridge and up to 1 month in the freezer, separated with parchment paper. Reheat in a toaster or skillet until hot and lightly crisp."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"2eb7dcfd-686e-5d67-bc7b-b81bef238d13","recipe_group_id":"bf8c875f-0372-4866-9be5-088c07d19cbe","language":"fr","slug":"pancakes-fraises-myrtilles","public_path":"/fr/pancakes-fraises-myrtilles","source_url":null,"title":"Pancakes aux fraises et aux myrtilles","excerpt":"Pancakes moelleux aux fraises et aux myrtilles fraîches, prêts en 30 minutes : une pâte à la farine, à l’œuf et au lait cuite avec les fruits, nappée de fruits frais. Donne 8 pancakes.","summary":"Ces pancakes se préparent avec une pâte simple à la farine, à l’œuf, au lait et au beurre fondu, allégée par la levure chimique. Les fraises et les myrtilles sont réparties sur la pâte dans la poêle : elles cuisent dans le pancake et libèrent leur jus et leur parfum.\n\nIls cuisent à feu moyen, par portions de 60 ml de pâte, et se servent empilés avec encore des fruits frais et du sirop d’érable. La recette donne 8 pancakes, 2 par personne, en 30 minutes environ.","category":"Petit-déjeuner et brunch","difficulty":"Facile","course":"Petit-déjeuner","cuisine":"Américaine","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":4,"keywords":["pancakes aux fraises et aux myrtilles","pancakes aux fraises","pancakes aux myrtilles","recette de pancakes","pancakes maison","petit-déjeuner aux fruits"],"ingredients":[{"name":"farine de blé","amount":"125","unit":"g","group":"Ingrédients secs"},{"name":"sucre","amount":"25","unit":"g","group":"Ingrédients secs"},{"name":"levure chimique","amount":"8","unit":"g","group":"Ingrédients secs"},{"name":"sel","amount":"3","unit":"g","group":"Ingrédients secs"},{"name":"œuf","amount":"1","unit":"pièce","group":"Ingrédients liquides"},{"name":"lait","amount":"240","unit":"ml","group":"Ingrédients liquides"},{"name":"beurre doux, fondu","amount":"33","unit":"g","group":"Ingrédients liquides"},{"name":"extrait de vanille","amount":"5","unit":"ml","group":"Ingrédients liquides"},{"name":"fraises en tranches","amount":"150","unit":"g","group":"Fruits et pour servir"},{"name":"myrtilles fraîches","amount":"100","unit":"g","group":"Fruits et pour servir"},{"name":"sirop d’érable","amount":"80","unit":"ml","group":"Fruits et pour servir"}],"steps":[{"title":"Mélanger les ingrédients secs","content":"Dans un grand bol, mélangez au fouet 125 g de farine (1 tasse), 25 g de sucre, 8 g de levure chimique (2 cuillères à café) et 3 g de sel (½ cuillère à café).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-01.webp","image_alt":"Pancakes aux fraises et aux myrtilles: Mélanger les ingrédients secs"},{"title":"Battre les ingrédients liquides","content":"Dans un autre bol, battez 1 œuf avec 240 ml de lait (1 tasse), 28 g de beurre fondu (2 cuillères à soupe) et 5 ml d’extrait de vanille.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-02.webp","image_alt":"Pancakes aux fraises et aux myrtilles: Battre les ingrédients liquides"},{"title":"Réunir les deux mélanges","content":"Versez les liquides sur les secs et mélangez à la spatule juste jusqu’à incorporation ; quelques petits grumeaux doivent rester. Laissez reposer la pâte 5 minutes.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-03.webp","image_alt":"Pancakes aux fraises et aux myrtilles: Réunir les deux mélanges"},{"title":"Chauffer la poêle","content":"Chauffez une poêle antiadhésive à feu moyen et graissez-la d’un fin film de beurre (environ 5 g).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-04.webp","image_alt":"Pancakes aux fraises et aux myrtilles: Chauffer la poêle"},{"title":"Verser la pâte et ajouter les fruits","content":"Versez 60 ml de pâte (une petite louche) par pancake. Répartissez un peu de fruits sur chacun, soit 100 g de fraises en tranches et 60 g de myrtilles au total pour les 8 pancakes.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-05.webp","image_alt":"Pancakes aux fraises et aux myrtilles: Verser la pâte et ajouter les fruits"},{"title":"Cuire et retourner","content":"Faites cuire 2 à 3 minutes, jusqu’à ce que des bulles apparaissent à la surface et que les bords soient fermes. Retournez et poursuivez 1 à 2 minutes, jusqu’à ce qu’ils soient dorés.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-06.webp","image_alt":"Pancakes aux fraises et aux myrtilles: Cuire et retourner"},{"title":"Répéter et garder au chaud","content":"Répétez avec le reste de la pâte jusqu’à obtenir 8 pancakes, en beurrant à nouveau la poêle si besoin. Gardez les pancakes cuits couverts d’un torchon propre.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-07.webp","image_alt":"Pancakes aux fraises et aux myrtilles: Répéter et garder au chaud"},{"title":"Servir","content":"Servez les pancakes empilés, 2 par personne, avec les 50 g de fraises et 40 g de myrtilles restants et du sirop d’érable (environ 80 ml au total).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-08.webp","image_alt":"Pancakes aux fraises et aux myrtilles: Servir"}],"image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","gallery":[{"url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","alt":"Pancakes aux fraises et aux myrtilles"}],"notes":"Ne mélangez pas trop la pâte : quelques grumeaux sont normaux et rendent les pancakes plus moelleux. Si la poêle est trop chaude, ils dorent dehors et restent crus dedans ; baissez le feu. Ils contiennent du gluten, des œufs et du lait. Ils se conservent 2 jours au réfrigérateur dans une boîte hermétique et se réchauffent au grille-pain ou à la poêle. Ils se congèlent aussi, séparés par du papier sulfurisé, jusqu’à 1 mois.","nutrition":{"calories":352,"protein_g":7.3,"carbs_g":58,"fat_g":10.4,"sodium_mg":552,"serving_size":"2 pancakes avec fruits et sirop (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutriments pour 100 g multipliés par le poids des ingrédients crus et divisés par 4. Le lait est calculé à 247 g, l’œuf à 50 g, la vanille (5 ml) à 4 g, le sirop d’érable (80 ml) à 106 g et le beurre à 33 g (28 g dans la pâte et environ 5 g pour la poêle).","note":"Estimation par portion ; elle varie selon les marques et la quantité de sirop. La levure chimique apporte l’essentiel du sodium."},"seo":{"title":"Pancakes aux fraises et myrtilles | Manual de Cocina","description":"Pancakes aux fraises et aux myrtilles : pâte moelleuse à la farine, à l’œuf et au lait, cuite avec des fruits frais et servie au sirop d’érable. Donne 8 pancakes.","image_variants":["/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-1x1.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-4x3.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-16x9.webp"],"faq":[{"q":"Puis-je utiliser des fraises ou des myrtilles surgelées ?","a":"Oui, sans les décongeler pour qu’elles libèrent moins de jus et ne colorent pas la pâte. Posez-les sur la pâte dans la poêle et ajoutez 1 minute de cuisson par face."},{"q":"Pourquoi mes pancakes sont-ils caoutchouteux ou plats ?","a":"C’est généralement dû à une pâte trop mélangée ou à une levure chimique périmée. Mélangez juste jusqu’à incorporation, laissez reposer 5 minutes et vérifiez la date de la levure."},{"q":"Peut-on les préparer à l’avance ?","a":"Oui. Ils se conservent 2 jours au réfrigérateur et jusqu’à 1 mois au congélateur, séparés par du papier sulfurisé. Réchauffez-les au grille-pain ou à la poêle jusqu’à ce qu’ils soient chauds et légèrement croustillants."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"446b73f2-cd5e-55fb-b25f-8001d23225ee","recipe_group_id":"bf8c875f-0372-4866-9be5-088c07d19cbe","language":"it","slug":"pancake-con-fragole-e-mirtilli","public_path":"/it/pancake-con-fragole-e-mirtilli","source_url":null,"title":"Pancake con fragole e mirtilli","excerpt":"Pancake soffici con fragole e mirtilli freschi, pronti in 30 minuti: una pastella di farina, uovo e latte cotta con la frutta e completata con altra frutta fresca. Dà 8 pancake.","summary":"Questi pancake si preparano con una pastella semplice di farina, uovo, latte e burro fuso, alleggerita dal lievito per dolci. Le fragole e i mirtilli si distribuiscono sulla pastella in padella, così cuociono dentro il pancake e rilasciano succo e profumo.\n\nSi cuociono a fuoco medio, con porzioni di 60 ml di pastella, e si servono impilati con altra frutta fresca e sciroppo d’acero. La ricetta dà 8 pancake, 2 a persona, in circa 30 minuti.","category":"Colazione e brunch","difficulty":"Facile","course":"Colazione","cuisine":"Americana","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":4,"keywords":["pancake con fragole e mirtilli","pancake alle fragole","pancake ai mirtilli","ricetta dei pancake","pancake fatti in casa","colazione con la frutta"],"ingredients":[{"name":"farina di frumento","amount":"125","unit":"g","group":"Ingredienti secchi"},{"name":"zucchero","amount":"25","unit":"g","group":"Ingredienti secchi"},{"name":"lievito per dolci","amount":"8","unit":"g","group":"Ingredienti secchi"},{"name":"sale","amount":"3","unit":"g","group":"Ingredienti secchi"},{"name":"uovo","amount":"1","unit":"pezzo","group":"Ingredienti liquidi"},{"name":"latte","amount":"240","unit":"ml","group":"Ingredienti liquidi"},{"name":"burro non salato, fuso","amount":"33","unit":"g","group":"Ingredienti liquidi"},{"name":"estratto di vaniglia","amount":"5","unit":"ml","group":"Ingredienti liquidi"},{"name":"fragole a fette","amount":"150","unit":"g","group":"Frutta e per servire"},{"name":"mirtilli freschi","amount":"100","unit":"g","group":"Frutta e per servire"},{"name":"sciroppo d’acero","amount":"80","unit":"ml","group":"Frutta e per servire"}],"steps":[{"title":"Mescola gli ingredienti secchi","content":"In una ciotola grande, mescola con una frusta 125 g di farina (1 tazza), 25 g di zucchero, 8 g di lievito per dolci (2 cucchiaini) e 3 g di sale (½ cucchiaino).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-01.webp","image_alt":"Pancake con fragole e mirtilli: Mescola gli ingredienti secchi"},{"title":"Sbatti gli ingredienti liquidi","content":"In un’altra ciotola, sbatti 1 uovo con 240 ml di latte (1 tazza), 28 g di burro fuso (2 cucchiai) e 5 ml di estratto di vaniglia.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-02.webp","image_alt":"Pancake con fragole e mirtilli: Sbatti gli ingredienti liquidi"},{"title":"Unisci i due composti","content":"Versa i liquidi sugli ingredienti secchi e mescola con una spatola solo finché sono amalgamati; devono restare alcuni piccoli grumi. Lascia riposare la pastella 5 minuti.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-03.webp","image_alt":"Pancake con fragole e mirtilli: Unisci i due composti"},{"title":"Scalda la padella","content":"Scalda una padella antiaderente a fuoco medio e ungila con un velo sottile di burro (circa 5 g).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-04.webp","image_alt":"Pancake con fragole e mirtilli: Scalda la padella"},{"title":"Versa la pastella e aggiungi la frutta","content":"Versa 60 ml di pastella (un piccolo mestolo) per ogni pancake. Distribuisci un po’ di frutta su ciascuno, in totale 100 g di fragole a fette e 60 g di mirtilli per gli 8 pancake.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-05.webp","image_alt":"Pancake con fragole e mirtilli: Versa la pastella e aggiungi la frutta"},{"title":"Cuoci e gira","content":"Cuoci 2–3 minuti, finché compaiono bollicine in superficie e i bordi sono rassodati. Gira e cuoci ancora 1–2 minuti, fino a doratura.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-06.webp","image_alt":"Pancake con fragole e mirtilli: Cuoci e gira"},{"title":"Ripeti e tieni al caldo","content":"Ripeti con la pastella rimasta fino a ottenere 8 pancake, ungendo di nuovo la padella se serve. Tieni i pancake già cotti coperti con un canovaccio pulito.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-07.webp","image_alt":"Pancake con fragole e mirtilli: Ripeti e tieni al caldo"},{"title":"Servi","content":"Servi i pancake impilati, 2 a persona, con i restanti 50 g di fragole e 40 g di mirtilli sopra e sciroppo d’acero (circa 80 ml in tutto).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-08.webp","image_alt":"Pancake con fragole e mirtilli: Servi"}],"image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","gallery":[{"url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","alt":"Pancake con fragole e mirtilli"}],"notes":"Non mescolare troppo la pastella: qualche grumo è normale e rende i pancake più soffici. Se la padella è troppo calda, si dorano fuori e restano crudi dentro; abbassa il fuoco. Contengono glutine, uova e latte. Si conservano 2 giorni in frigorifero in un contenitore ermetico e si riscaldano nel tostapane o in padella. Si possono anche congelare, separati con carta forno, fino a 1 mese.","nutrition":{"calories":352,"protein_g":7.3,"carbs_g":58,"fat_g":10.4,"sodium_mg":552,"serving_size":"2 pancake con frutta e sciroppo (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrienti per 100 g moltiplicati per il peso degli ingredienti crudi e divisi per 4. Il latte è calcolato a 247 g, l’uovo a 50 g, la vaniglia (5 ml) a 4 g, lo sciroppo d’acero (80 ml) a 106 g e il burro a 33 g (28 g nella pastella e circa 5 g per la padella).","note":"Stima per porzione; varia con le marche e la quantità di sciroppo. Il lievito per dolci apporta la maggior parte del sodio."},"seo":{"title":"Pancake con fragole e mirtilli | Manual de Cocina","description":"Pancake con fragole e mirtilli: pastella soffice di farina, uovo e latte cotta con frutta fresca e servita con sciroppo d’acero. Dà 8 pancake.","image_variants":["/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-1x1.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-4x3.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-16x9.webp"],"faq":[{"q":"Posso usare fragole o mirtilli surgelati?","a":"Sì, senza scongelarli, così rilasciano meno succo e non colorano la pastella. Mettili sulla pastella in padella e cuoci 1 minuto in più per lato."},{"q":"Perché i miei pancake vengono gommosi o piatti?","a":"Quasi sempre la pastella è stata mescolata troppo o il lievito è scaduto. Mescola solo fino ad amalgamare, lascia riposare 5 minuti e controlla la data del lievito."},{"q":"Si possono preparare in anticipo?","a":"Sì. Si conservano 2 giorni in frigorifero e fino a 1 mese in freezer, separati con carta forno. Riscaldali nel tostapane o in padella finché sono caldi e leggermente croccanti."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"1e4cf001-be8d-55e6-8465-a5b2c30fb7d2","recipe_group_id":"bf8c875f-0372-4866-9be5-088c07d19cbe","language":"ja","slug":"いちごとブルーベリーのパンケーキ","public_path":"/ja/いちごとブルーベリーのパンケーキ","source_url":null,"title":"いちごとブルーベリーのパンケーキ","excerpt":"フレッシュないちごとブルーベリーをのせて焼くふわふわパンケーキ。小麦粉・卵・牛乳の生地で、30分で完成。8枚分の作り方です。","summary":"このパンケーキは、小麦粉・卵・牛乳・溶かしバターのシンプルな生地にベーキングパウダーを加えてふんわり仕上げます。いちごとブルーベリーはフライパンの生地の上に散らして焼くので、パンケーキの中で火が通り、果汁と香りが広がります。\n\n中火で生地を60mlずつ焼き、仕上げにフレッシュなフルーツとメープルシロップを添えて重ねます。8枚分（1人2枚）で、約30分でできあがります。","category":"朝食・ブランチ","difficulty":"簡単","course":"朝食","cuisine":"アメリカ料理","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":4,"keywords":["いちごとブルーベリーのパンケーキ","いちごパンケーキ","ブルーベリーパンケーキ","パンケーキのレシピ","手作りパンケーキ","フルーツ朝食"],"ingredients":[{"name":"薄力粉","amount":"125","unit":"g","group":"粉類"},{"name":"砂糖","amount":"25","unit":"g","group":"粉類"},{"name":"ベーキングパウダー","amount":"8","unit":"g","group":"粉類"},{"name":"塩","amount":"3","unit":"g","group":"粉類"},{"name":"卵","amount":"1","unit":"個","group":"液体の材料"},{"name":"牛乳","amount":"240","unit":"ml","group":"液体の材料"},{"name":"無塩バター（溶かす）","amount":"33","unit":"g","group":"液体の材料"},{"name":"バニラエクストラクト","amount":"5","unit":"ml","group":"液体の材料"},{"name":"いちご（スライス）","amount":"150","unit":"g","group":"フルーツと仕上げ"},{"name":"ブルーベリー（生）","amount":"100","unit":"g","group":"フルーツと仕上げ"},{"name":"メープルシロップ","amount":"80","unit":"ml","group":"フルーツと仕上げ"}],"steps":[{"title":"粉類を混ぜる","content":"大きめのボウルに薄力粉125g（1カップ）、砂糖25g、ベーキングパウダー8g（小さじ2）、塩3g（小さじ1/2）を入れ、泡立て器で混ぜます。","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-01.webp","image_alt":"いちごとブルーベリーのパンケーキ: 粉類を混ぜる"},{"title":"液体の材料を混ぜる","content":"別のボウルに卵1個、牛乳240ml（1カップ）、溶かしバター28g（大さじ2）、バニラエクストラクト5mlを入れて混ぜます。","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-02.webp","image_alt":"いちごとブルーベリーのパンケーキ: 液体の材料を混ぜる"},{"title":"2つを合わせる","content":"液体を粉類に加え、ゴムベラで粉っぽさがなくなるまでさっくり混ぜます。小さなダマが少し残るくらいで大丈夫です。生地を5分休ませます。","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-03.webp","image_alt":"いちごとブルーベリーのパンケーキ: 2つを合わせる"},{"title":"フライパンを温める","content":"フッ素樹脂加工のフライパンを中火で温め、バター（約5g）を薄くなじませます。","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-04.webp","image_alt":"いちごとブルーベリーのパンケーキ: フライパンを温める"},{"title":"生地を流してフルーツをのせる","content":"1枚につき生地60ml（小さめのお玉1杯）を流します。それぞれにフルーツを散らし、8枚分でスライスしたいちご合計100gとブルーベリー合計60gを使います。","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-05.webp","image_alt":"いちごとブルーベリーのパンケーキ: 生地を流してフルーツをのせる"},{"title":"焼いて返す","content":"2〜3分、表面に気泡が出て縁が固まるまで焼きます。裏返してさらに1〜2分、きつね色になるまで焼きます。","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-06.webp","image_alt":"いちごとブルーベリーのパンケーキ: 焼いて返す"},{"title":"繰り返して保温する","content":"残りの生地でも同様に焼き、全部で8枚にします。必要ならフライパンにバターを足します。焼けたパンケーキは清潔な布巾をかけて保温します。","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-07.webp","image_alt":"いちごとブルーベリーのパンケーキ: 繰り返して保温する"},{"title":"盛りつける","content":"パンケーキを重ねて1人2枚ずつ盛り、残りのいちご50gとブルーベリー40gをのせ、メープルシロップ（合計約80ml）をかけます。","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-08.webp","image_alt":"いちごとブルーベリーのパンケーキ: 盛りつける"}],"image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","gallery":[{"url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","alt":"いちごとブルーベリーのパンケーキ"}],"notes":"生地を混ぜすぎないようにしてください。小さなダマが残るほうがふんわり仕上がります。フライパンが熱すぎると、外側だけ焦げて中が生焼けになるので火を弱めてください。小麦（グルテン）、卵、乳を含みます。密閉容器に入れて冷蔵で2日間保存でき、トースターやフライパンで温め直せます。オーブンシートで1枚ずつ分ければ、冷凍で1か月まで保存できます。","nutrition":{"calories":352,"protein_g":7.3,"carbs_g":58,"fat_g":10.4,"sodium_mg":552,"serving_size":"フルーツとシロップ付き2枚分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養成分に、生の材料の重量を掛けて合計し、4で割りました。牛乳は247g、卵は50g、バニラ（5ml）は4g、メープルシロップ（80ml）は106g、バターは33g（生地に28g、フライパン用に約5g）で計算しています。","note":"1人分の推定値です。商品やシロップの量によって異なります。ナトリウムの大部分はベーキングパウダー由来です。"},"seo":{"title":"いちごとブルーベリーのパンケーキ | Manual de Cocina","description":"いちごとブルーベリーをのせて焼くふわふわパンケーキ。小麦粉・卵・牛乳の生地にメープルシロップを添えて、8枚分の作り方です。","image_variants":["/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-1x1.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-4x3.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-16x9.webp"],"faq":[{"q":"冷凍のいちごやブルーベリーでも作れますか？","a":"はい。果汁が出すぎず生地に色移りしにくいよう、凍ったまま使います。フライパンの生地の上にのせ、片面あたり1分長めに焼いてください。"},{"q":"パンケーキがゴムのようになったり、平らになるのはなぜですか？","a":"多くは生地の混ぜすぎ、またはベーキングパウダーの劣化が原因です。粉っぽさがなくなる程度に混ぜ、5分休ませ、ベーキングパウダーの期限も確認してください。"},{"q":"作り置きできますか？","a":"できます。冷蔵で2日間、オーブンシートで分ければ冷凍で1か月保存できます。トースターやフライパンで、温かく少しカリッとするまで温め直してください。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"1ddba79f-bd25-51f2-bcfa-ee326051b86e","recipe_group_id":"bf8c875f-0372-4866-9be5-088c07d19cbe","language":"pt","slug":"panquecas-com-morangos-e-mirtilos","public_path":"/pt/panquecas-com-morangos-e-mirtilos","source_url":null,"title":"Panquecas americanas com morangos e mirtilos","excerpt":"Panquecas americanas fofinhas com morangos e mirtilos frescos, prontas em 30 minutos: massa de farinha, ovo e leite cozida com as frutas e finalizada com mais fruta fresca. Rende 8 panquecas.","summary":"Estas panquecas são feitas com uma massa simples de farinha, ovo, leite e manteiga derretida, aerada com fermento em pó. Os morangos e os mirtilos são distribuídos sobre a massa na frigideira, então cozinham dentro da panqueca e soltam seu suco e aroma.\n\nSão feitas em fogo médio, com porções de 60 ml de massa, e servidas empilhadas com mais fruta fresca e xarope de bordo. A receita rende 8 panquecas, 2 por pessoa, em cerca de 30 minutos.","category":"Café da manhã e brunch","difficulty":"Fácil","course":"Café da manhã","cuisine":"Americana","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":30,"servings":4,"keywords":["panquecas com morangos e mirtilos","panqueca de morango","panqueca de mirtilo","receita de panqueca americana","panquecas caseiras","café da manhã com frutas"],"ingredients":[{"name":"farinha de trigo","amount":"125","unit":"g","group":"Ingredientes secos"},{"name":"açúcar","amount":"25","unit":"g","group":"Ingredientes secos"},{"name":"fermento em pó","amount":"8","unit":"g","group":"Ingredientes secos"},{"name":"sal","amount":"3","unit":"g","group":"Ingredientes secos"},{"name":"ovo","amount":"1","unit":"unidade","group":"Ingredientes líquidos"},{"name":"leite","amount":"240","unit":"ml","group":"Ingredientes líquidos"},{"name":"manteiga sem sal, derretida","amount":"33","unit":"g","group":"Ingredientes líquidos"},{"name":"extrato de baunilha","amount":"5","unit":"ml","group":"Ingredientes líquidos"},{"name":"morangos fatiados","amount":"150","unit":"g","group":"Frutas e para servir"},{"name":"mirtilos frescos","amount":"100","unit":"g","group":"Frutas e para servir"},{"name":"xarope de bordo","amount":"80","unit":"ml","group":"Frutas e para servir"}],"steps":[{"title":"Misture os ingredientes secos","content":"Em uma tigela grande, misture com um fouet 125 g de farinha (1 xícara), 25 g de açúcar, 8 g de fermento em pó (2 colheres de chá) e 3 g de sal (½ colher de chá).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-01.webp","image_alt":"Panquecas americanas com morangos e mirtilos: Misture os ingredientes secos"},{"title":"Bata os ingredientes líquidos","content":"Em outra tigela, bata 1 ovo com 240 ml de leite (1 xícara), 28 g de manteiga derretida (2 colheres de sopa) e 5 ml de extrato de baunilha.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-02.webp","image_alt":"Panquecas americanas com morangos e mirtilos: Bata os ingredientes líquidos"},{"title":"Junte as duas misturas","content":"Despeje os líquidos sobre os secos e misture com uma espátula só até incorporar; devem ficar alguns grumos pequenos. Deixe a massa descansar por 5 minutos.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-03.webp","image_alt":"Panquecas americanas com morangos e mirtilos: Junte as duas misturas"},{"title":"Aqueça a frigideira","content":"Aqueça uma frigideira antiaderente em fogo médio e unte com uma fina camada de manteiga (cerca de 5 g).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-04.webp","image_alt":"Panquecas americanas com morangos e mirtilos: Aqueça a frigideira"},{"title":"Despeje a massa e acrescente a fruta","content":"Despeje 60 ml de massa (uma concha pequena) para cada panqueca. Distribua um pouco de fruta sobre cada uma, no total 100 g de morangos fatiados e 60 g de mirtilos para as 8 panquecas.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-05.webp","image_alt":"Panquecas americanas com morangos e mirtilos: Despeje a massa e acrescente a fruta"},{"title":"Cozinhe e vire","content":"Cozinhe por 2–3 minutos, até surgirem bolhas na superfície e as bordas ficarem firmes. Vire e cozinhe mais 1–2 minutos, até dourar.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-06.webp","image_alt":"Panquecas americanas com morangos e mirtilos: Cozinhe e vire"},{"title":"Repita e mantenha aquecidas","content":"Repita com o restante da massa até ter 8 panquecas, untando a frigideira de novo se precisar. Mantenha as já prontas cobertas com um pano limpo.","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-07.webp","image_alt":"Panquecas americanas com morangos e mirtilos: Repita e mantenha aquecidas"},{"title":"Sirva","content":"Sirva as panquecas empilhadas, 2 por pessoa, com os 50 g de morangos e 40 g de mirtilos restantes por cima e xarope de bordo (cerca de 80 ml no total).","image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/paso-08.webp","image_alt":"Panquecas americanas com morangos e mirtilos: Sirva"}],"image_url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","gallery":[{"url":"/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada.webp","alt":"Panquecas americanas com morangos e mirtilos"}],"notes":"Não misture demais a massa: alguns grumos são normais e deixam as panquecas mais fofas. Se a frigideira estiver muito quente, elas dourarão por fora e ficarão cruas por dentro; baixe o fogo. Contêm glúten, ovo e leite. Duram 2 dias na geladeira em recipiente hermético e podem ser reaquecidas na torradeira ou na frigideira. Também podem ser congeladas, separadas com papel-manteiga, por até 1 mês.","nutrition":{"calories":352,"protein_g":7.3,"carbs_g":58,"fat_g":10.4,"sodium_mg":552,"serving_size":"2 panquecas com fruta e xarope (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrientes por 100 g multiplicados pelo peso dos ingredientes crus e divididos por 4. O leite é calculado a 247 g, o ovo a 50 g, a baunilha (5 ml) a 4 g, o xarope de bordo (80 ml) a 106 g e a manteiga a 33 g (28 g na massa e cerca de 5 g para a frigideira).","note":"Estimativa por porção; varia conforme as marcas e a quantidade de xarope. O fermento em pó fornece a maior parte do sódio."},"seo":{"title":"Panquecas com morangos e mirtilos | Manual de Cocina","description":"Panquecas americanas com morangos e mirtilos: massa fofinha de farinha, ovo e leite, cozida com fruta fresca e servida com xarope de bordo. Rende 8 panquecas.","image_variants":["/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-1x1.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-4x3.webp","/recetas/receta-de-pancakes-con-fresas-y-arandanos/portada-16x9.webp"],"faq":[{"q":"Posso usar morangos ou mirtilos congelados?","a":"Pode, sem descongelar, para soltarem menos suco e não mancharem a massa. Coloque-os sobre a massa na frigideira e cozinhe 1 minuto a mais de cada lado."},{"q":"Por que minhas panquecas ficam borrachudas ou achatadas?","a":"Quase sempre a massa foi misturada demais ou o fermento está velho. Misture só até incorporar, deixe descansar 5 minutos e confira a validade do fermento."},{"q":"Posso preparar com antecedência?","a":"Pode. Duram 2 dias na geladeira e até 1 mês no congelador, separadas com papel-manteiga. Reaqueça na torradeira ou na frigideira até ficarem quentes e levemente crocantes."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-de-pancakes-con-fresas-y-arandanos') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
